const uint16_t *AI_Avatar_GetImage(AvatarState state)
{
    switch (state)
    {
        case AVATAR_NORMAL_IDLE:
            return gAvatar_NormalIdle;
        case AVATAR_THINKING:
            return gAvatar_Thinking;
        case AVATAR_HAPPY:
            return gAvatar_Happy;
        case AVATAR_TIRED:
            return gAvatar_Tired;
        case AVATAR_CURIOUS:
            return gAvatar_Curious;
        case AVATAR_GENTLE:
            return gAvatar_Gentle;
        case AVATAR_SHY:
            return gAvatar_Shy;
        case AVATAR_NORMAL_IDLE:
        default:
            return gAvatar_NormalIdle;
    }
}
